import sys

def len_block(n):
    if n <= 0:
        return 0
    total = 0
    start = 1
    digits = 1
    while start <= n:
        end = min(n, start * 10 - 1)
        count = end - start + 1
        total += count * digits
        start *= 10
        digits += 1
    return total

def total_len(m):
    if m <= 0:
        return 0
    total = 0
    start = 1
    digits = 1
    prev_len = 0
    while start <= m:
        end = min(m, start * 10 - 1)
        count = end - start + 1
        total += count * prev_len + digits * (count * (count + 1) // 2)
        prev_len += count * digits
        start *= 10
        digits += 1
    return total

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    q = int(data[0])
    queries = list(map(int, data[1:1 + q]))
    out = []
    for k in queries:
        lo, hi = 1, 1
        while total_len(hi) < k:
            hi *= 2
        while lo < hi:
            mid = (lo + hi) // 2
            if total_len(mid) >= k:
                hi = mid
            else:
                lo = mid + 1
        m = lo
        pos_in_block = k - total_len(m - 1)

        lo, hi = 1, m
        while lo < hi:
            mid = (lo + hi) // 2
            if len_block(mid) >= pos_in_block:
                hi = mid
            else:
                lo = mid + 1
        x = lo
        pos_in_num = pos_in_block - len_block(x - 1)
        out.append(str(x)[pos_in_num - 1])
    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()
